var keyCode = e.which ? e.which : e.keyCode
var ret = ((keyCode = 48 &amp;&amp; keyCode = 57) || specialKeys.indexOf(keyCode) != -1);
$(.error).css(display, ret ? none : inline);
return ret;
});
