function getUrlVars() {
var vars = [], hash;
var hashes = window.location.href.slice(window.location.href.indexOf(&apos;?&apos;) + 1).split(&apos;&amp;&apos;);
for (var i = 0; i  hashes.length; i++) {
hash = hashes[i].split(&apos;=&apos;);
vars.push(hash[0]);
vars[hash[0]] = hash[1];
}
return vars;
}

